"use client";

import { cva, type VariantProps } from "class-variance-authority";
import type { ComponentPropsWithRef, ReactNode } from "react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils";
import { useIconSource } from "./hooks/use-icon-source";
import { useImageBackground } from "./hooks/use-image-background";
import type { CryptoIdentityIcon } from "./lib/types";

export type { CryptoIdentityIcon } from "./lib/types";

const adaptiveBackground =
  "[background:var(--crypto-identity-light-surface)] dark:[background:var(--crypto-identity-dark-surface)]";

export const cryptoIdentityVariants = cva("inline-flex", {
  variants: {
    variant: {
      avatar: "relative size-8 shrink-0",
      badge:
        "min-w-0 items-center gap-1.5 rounded-full bg-secondary px-2 py-1 text-secondary-foreground",
      label: "min-w-0 items-center gap-2",
    },
  },
  defaultVariants: {
    variant: "avatar",
  },
});

const avatarVariants = cva("", {
  variants: {
    variant: {
      avatar: "size-full",
      badge: "size-4",
      label: "size-5",
    },
  },
  defaultVariants: {
    variant: "avatar",
  },
});

export type CryptoIdentityVariant = NonNullable<
  VariantProps<typeof cryptoIdentityVariants>["variant"]
>;

export interface CryptoIdentityProps extends ComponentPropsWithRef<"span"> {
  icon: CryptoIdentityIcon;
  cornerIcon?: CryptoIdentityIcon | undefined;
  fallback?: ReactNode | undefined;
  cornerFallback?: ReactNode | undefined;
  preferredBaseUrl?: string | undefined;
  variant?: CryptoIdentityVariant;
}

export function CryptoIdentity({
  children,
  className,
  cornerFallback,
  cornerIcon,
  fallback,
  icon,
  preferredBaseUrl,
  variant = "avatar",
  ref,
  ...props
}: CryptoIdentityProps) {
  const image = useIconSource(icon, preferredBaseUrl);
  const corner = useIconSource(cornerIcon, preferredBaseUrl);
  const imageBackground = useImageBackground(image.src);
  const cornerBackground = useImageBackground(corner.src);
  const imageLoading = image.isResolving || Boolean(image.src && !imageBackground.isLoaded);
  const cornerLoading = corner.isResolving || Boolean(corner.src && !cornerBackground.isLoaded);

  return (
    <span
      ref={ref}
      data-slot="crypto-identity"
      className={cn(cryptoIdentityVariants({ variant }), className)}
      {...props}
    >
      <span
        data-slot="crypto-identity-avatar"
        className={cn("relative inline-flex shrink-0", avatarVariants({ variant }))}
      >
        <Avatar
          aria-busy={imageLoading || undefined}
          data-slot="crypto-identity-image"
          className={cn("size-full bg-muted", imageBackground.style && adaptiveBackground)}
          style={imageBackground.style}
        >
          {image.src ? (
            <AvatarImage
              alt={variant === "avatar" ? icon.name : ""}
              className="dark:filter-(--crypto-identity-dark-filter,none)"
              crossOrigin={imageBackground.crossOrigin}
              src={image.src}
              onError={image.handleError}
              onLoad={imageBackground.handleLoad}
            />
          ) : null}
          <AvatarFallback>{fallback}</AvatarFallback>
          {imageLoading ? (
            <Skeleton
              aria-hidden="true"
              data-slot="crypto-identity-skeleton"
              className="pointer-events-none absolute inset-0 size-full rounded-full"
            />
          ) : null}
        </Avatar>
        {cornerIcon ? (
          <Avatar
            aria-busy={cornerLoading || undefined}
            data-slot="crypto-identity-corner"
            className={cn(
              "absolute -right-0.5 -bottom-0.5 size-[40%] min-h-3 min-w-3 bg-muted ring-2 ring-background",
              cornerBackground.style && adaptiveBackground,
            )}
            style={cornerBackground.style}
          >
            {corner.src ? (
              <AvatarImage
                alt=""
                className="dark:filter-(--crypto-identity-dark-filter,none)"
                crossOrigin={cornerBackground.crossOrigin}
                src={corner.src}
                onError={corner.handleError}
                onLoad={cornerBackground.handleLoad}
              />
            ) : null}
            <AvatarFallback>{cornerFallback}</AvatarFallback>
            {cornerLoading ? (
              <Skeleton
                aria-hidden="true"
                data-slot="crypto-identity-corner-skeleton"
                className="pointer-events-none absolute inset-0 size-full rounded-full"
              />
            ) : null}
          </Avatar>
        ) : null}
      </span>
      {variant === "avatar" ? null : (
        <span data-slot="crypto-identity-label" className="truncate">
          {children}
        </span>
      )}
    </span>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { normalize, normalizeAssetName, normalizeNetworkSlug } from "../lib/normalize";
import { resolveIconUrls } from "../lib/resolve-icon-urls";
import type { CryptoIdentityIcon } from "../lib/types";

export function useIconSource(icon?: CryptoIdentityIcon, preferredBaseUrl?: string) {
  const key = `${stableIconKey(icon)}:${preferredBaseUrl ?? ""}`;
  const iconRef = useRef(icon);
  iconRef.current = icon;
  const [result, setResult] = useState<{ key: string; sources: string[] }>({
    key: "",
    sources: [],
  });
  const [index, setIndex] = useState(0);
  const sources = result.key === key ? result.sources : [];

  useEffect(() => {
    const currentIcon = iconRef.current;
    setIndex(0);
    let cancelled = false;

    if (!currentIcon) {
      return;
    }

    resolveIconUrls(currentIcon, preferredBaseUrl).then((urls) => {
      if (cancelled) {
        return;
      }
      setResult({ key, sources: urls });
    });

    return () => {
      cancelled = true;
    };
  }, [key, preferredBaseUrl]);

  const handleError = useCallback(() => {
    setIndex((value) => Math.min(value + 1, sources.length));
  }, [sources.length]);

  return {
    src: sources[index],
    isResolving: Boolean(icon) && result.key !== key,
    handleError,
  };
}

function stableIconKey(icon?: CryptoIdentityIcon): string {
  if (!icon) {
    return "";
  }
  return [
    icon.type,
    normalizeAssetName(icon.type, icon.name),
    icon.type === "token" ? normalizeNetworkSlug(icon.network) : "",
    icon.type === "token" ? normalize(icon.contractAddress) : "",
  ].join(":");
}

"use client";

import { FastAverageColor } from "fast-average-color";
import { type CSSProperties, type SyntheticEvent, useCallback, useState } from "react";

const averageColor = new FastAverageColor();
const BACKGROUND_CACHE_LIMIT = 100;
type IdentityBackground = CSSProperties & Record<string, string>;
const backgroundCache = new Map<string, IdentityBackground>();
const colorSamplingHosts = new Set([
  "cdn.jsdmirror.com",
  "cdn.jsdelivr.net",
  "fastly.jsdelivr.net",
  "gcore.jsdelivr.net",
  "raw.githubusercontent.com",
]);

export function useImageBackground(src?: string) {
  const canSample = supportsColorSampling(src);
  const [loadedSrc, setLoadedSrc] = useState<string>();
  const [sampled, setSampled] = useState<{
    src: string;
    style: IdentityBackground;
  }>();
  const background =
    sampled && sampled.src === src ? sampled.style : src ? backgroundCache.get(src) : undefined;

  const handleLoad = useCallback(
    (event: SyntheticEvent<HTMLImageElement>) => {
      if (!src) {
        return;
      }
      setLoadedSrc(src);
      if (!canSample || backgroundCache.has(src)) {
        return;
      }
      const result = averageColor.getColor(event.currentTarget, {
        algorithm: "sqrt",
        ignoredColor: [0, 0, 0, 0, 32],
        mode: "speed",
        silent: true,
      });
      if (!result.error) {
        const style = createBackgroundStyle(result.hex, result.value);
        cacheBackground(src, style);
        setSampled({ src, style });
      }
    },
    [canSample, src],
  );

  return {
    crossOrigin: canSample ? ("anonymous" as const) : undefined,
    handleLoad,
    isLoaded: Boolean(src) && loadedSrc === src,
    style: background,
  };
}

function createBackgroundStyle(
  hex: string,
  [red, green, blue]: [number, number, number, number],
): IdentityBackground {
  const chroma = Math.max(red, green, blue) - Math.min(red, green, blue);
  const luminance = red * 0.2126 + green * 0.7152 + blue * 0.0722;
  const color: Rgb = [red, green, blue];
  const style: IdentityBackground = {
    "--crypto-identity-color": hex,
    "--crypto-identity-light-surface": lightSurface(color, chroma, luminance),
    "--crypto-identity-dark-surface": darkSurface(color, luminance),
  };

  if (chroma <= 28 && luminance <= 72) {
    style["--crypto-identity-dark-filter"] = "invert(1)";
  }

  return style;
}

type Rgb = [number, number, number];

function lightSurface(color: Rgb, chroma: number, luminance: number): string {
  if (chroma <= 28 && luminance <= 72) {
    return "rgb(241 245 249)";
  }
  if (luminance >= 188) {
    return rgb(scaleToLuminance(color, 104, luminance));
  }
  return rgb(mix(color, [255, 255, 255], 0.82));
}

function darkSurface(color: Rgb, luminance: number): string {
  if (luminance <= 72) {
    return "rgb(24 24 27)";
  }
  return rgb(mix(color, [9, 11, 17], luminance >= 188 ? 0.78 : 0.72));
}

function scaleToLuminance(color: Rgb, target: number, luminance: number): Rgb {
  const factor = target / luminance;
  return color.map((channel) => channel * factor) as Rgb;
}

function mix(color: Rgb, surface: Rgb, surfaceRatio: number): Rgb {
  return color.map(
    (channel, index) => channel * (1 - surfaceRatio) + (surface[index] ?? 0) * surfaceRatio,
  ) as Rgb;
}

function rgb(color: Rgb): string {
  return `rgb(${color.map((channel) => Math.round(Math.max(0, Math.min(255, channel)))).join(" ")})`;
}

function cacheBackground(src: string, style: IdentityBackground): void {
  if (!backgroundCache.has(src) && backgroundCache.size >= BACKGROUND_CACHE_LIMIT) {
    const oldest = backgroundCache.keys().next().value;
    if (oldest) {
      backgroundCache.delete(oldest);
    }
  }
  backgroundCache.set(src, style);
}

function supportsColorSampling(src?: string): boolean {
  if (!src) {
    return false;
  }
  try {
    const url = new URL(src, window.location.href);
    return url.origin === window.location.origin || colorSamplingHosts.has(url.hostname);
  } catch {
    return false;
  }
}

export interface TokenAssetQuery {
  type: "token";
  /** Token symbol or asset name. Matching is case-insensitive. */
  name: string;
  /** Network name or common alias. Casing and separators are normalized internally. */
  network: string;
  /** Chain-specific token contract address. Matching is case-insensitive where applicable. */
  contractAddress?: string | null;
  /** @deprecated Assets are always resolved from the compressed catalog. */
  includeCatalog?: boolean;
}

interface CatalogAssetQuery<T extends "exchange" | "swap-provider" | "wallet"> {
  type: T;
  /** Catalog ID or display name. Casing and separators are normalized internally. */
  name: string;
  /** @deprecated Assets are always resolved from the compressed catalog. */
  includeCatalog?: boolean;
}

interface DappAssetQuery {
  type: "dapp";
  /** DApp ID or domain, with or without dots, separators, casing, or the PNG suffix. */
  name: string;
  /** @deprecated Assets are always resolved from the compressed catalog. */
  includeCatalog?: boolean;
}

interface NetworkAssetQuery {
  type: "network";
  /** Network name or common alias. Casing and separators are normalized internally. */
  name: string;
}

export type AssetQuery =
  | TokenAssetQuery
  | CatalogAssetQuery<"exchange">
  | CatalogAssetQuery<"swap-provider">
  | CatalogAssetQuery<"wallet">
  | NetworkAssetQuery
  | DappAssetQuery;

export type AssetType = AssetQuery["type"];
type WithoutCatalog<T> = T extends unknown ? Omit<T, "includeCatalog"> : never;

export type CryptoIdentityIcon = WithoutCatalog<AssetQuery>;

export { canonicalLogoUrl, resolveLogoUrls } from "./logo-urls";
export { resolveIconUrls } from "./resolve-icon-urls";
export type { AssetQuery, AssetType } from "./types";

export const ASSETS_REPOSITORY = "GMWalletApp/assets";
export const ASSETS_BRANCH = "main";

export const CDN_BASE_URLS = [
  `https://cdn.jsdmirror.com/gh/${ASSETS_REPOSITORY}@${ASSETS_BRANCH}`,
  `https://cdn.jsdelivr.net/gh/${ASSETS_REPOSITORY}@${ASSETS_BRANCH}`,
  `https://fastly.jsdelivr.net/gh/${ASSETS_REPOSITORY}@${ASSETS_BRANCH}`,
  `https://gcore.jsdelivr.net/gh/${ASSETS_REPOSITORY}@${ASSETS_BRANCH}`,
  `https://raw.githubusercontent.com/${ASSETS_REPOSITORY}/${ASSETS_BRANCH}`,
] as const;

export function orderedCdnBaseUrls(preferredBaseUrl?: string): string[] {
  if (!preferredBaseUrl) {
    return [...CDN_BASE_URLS];
  }
  const normalized = preferredBaseUrl.replace(/\/$/, "");
  return [normalized, ...CDN_BASE_URLS.filter((url) => url !== normalized)];
}

